insert:
QtObject {
id: p
property string mainText: ""
property real freezeTime: 15
property bool mainTextDisp: false
property bool strBufJudge: false
property int textMoveTime: 15
onMainTextDispChanged: {
if (mainTextDisp) {
useMarquee()
}
}
}
SCmnLabel {
id: labelTitle
x: 0
visible: !base.useLoop && (!p.mainTextDisp && isUseMarquee && p.strBufJudge)
text: p.mainText
font.pixelSize: pixelSize
font.weight: fontWeight
color: fontColor
horizontalAlignment: horizontal_alignment
verticalAlignment: Text.AlignVCenter
onWidthChanged: {
p.strBufJudge = (labelTitle.width > base.width) ? true : false
p.mainTextDisp = p.strBufJudge
}
}
XAnimator {
id: marqueeScroll
target:labelTitle
running: false
from: 0;
to: p.freezeTime - labelTitle.width - left_margin;
duration: (labelTitle.width + left_margin) * p.textMoveTime
onStarted: {
p.mainTextDisp = false
}
onStopped: {
p.mainTextDisp = true
}
}
SCmnLabel {
id: periodlabelTitle
width: base.width
visible: !base.useLoop && (p.mainTextDisp && ( p.strBufJudge || !isUseMarquee ))
text: p.mainText
font.pixelSize: pixelSize
font.weight: fontWeight
color: fontColor
horizontalAlignment: Text.AlignLeft
verticalAlignment: Text.AlignVCenter
}
SCmnLabel {
id: centerText
width: base.width
visible: !base.useLoop && (!p.strBufJudge)
text: p.mainText
font.pixelSize: pixelSize
font.weight: fontWeight
color: fontColor
horizontalAlignment: horizontal_alignment
verticalAlignment: Text.AlignVCenter
}
Timer {
id: fixingTime
interval: 2000
running: false
onTriggered: {
marqueeScroll.start()
}
}
function useMarquee() {
fixingTime.running = !base.useLoop && isUseMarquee ? p.strBufJudge : false
}
function checkMarqueeScroll() {
if (base.useLoop) { marqueeScroll.stop(); fixingTime.stop(); return }
if (isUseMarquee && p.mainText !== "") {
marqueeScroll.stop()
fixingTime.stop()
p.strBufJudge = (labelTitle.width > base.width) ? true : false
p.mainTextDisp = p.strBufJudge
labelTitle.x = 0
useMarquee()
} else if (fixingTime.running || marqueeScroll.running) {
marqueeScroll.stop()
fixingTime.stop()
}
}
onIsUseMarqueeChanged: {
checkMarqueeScroll()
}
Image
{
visible: !base.useLoop && (p.strBufJudge && marqueeScroll.running)
source: left_mask_image_path
anchors { left: parent.left; leftMargin: -left_margin; verticalCenter: parent.verticalCenter }
}
Image
{
visible: !base.useLoop && (p.strBufJudge)
source: right_mask_image_path
anchors { right: parent.right; verticalCenter: parent.verticalCenter }
}
Loader { id: loopLoader; anchors.fill: parent; active: base.continuous && base.visible; source: "file:///system/vendor/sony-peq/ui/ContinuousTitle.qml"; onLoaded: item.titleHost = base }
}
